package de.comahe.i18n4k.toolchain.tasks

import org.jetbrains.amper.plugins.ExecutionAvoidance
import org.jetbrains.amper.plugins.TaskAction
import java.nio.file.Path

/**
 * Deletes the directories generated by [generateI18n4kFiles].
 *
 * Registered as the custom command `clearI18n4kFiles`, mirroring the
 * `clearI18n4kFiles` task of the Gradle plugin.
 *
 * The paths are taken as `String` parameters on purpose: `Path` parameters would
 * make the Kotlin Toolchain infer a dependency on (or from) the generation task
 * and treat this task's effects as inputs/outputs.
 */
@TaskAction(executionAvoidance = ExecutionAvoidance.Disabled)
fun clearI18n4kFiles(
    generatedSourcesDir: String,
    generatedLanguageFilesDir: String,
) {
    for (path in listOf(generatedSourcesDir, generatedLanguageFilesDir)) {
        val dir = Path.of(path)
        if (dir.toFile().exists()) {
            println("i18n4k - deleting $dir")
            dir.toFile().deleteRecursively()
        }
    }
}
